use acer_device::Device;
use acer_protocol::{battery_care_ack,battery_care_readback,battery_validation_state,ApplyReport,ApplyStatus,BatteryCareState,Capabilities,DeviceError,Snapshot};
use serde::Serialize;use crate::validation::Outcome;
#[derive(Serialize)]pub struct Report{command:&'static str,outcome:Outcome,message:String,capabilities:Option<Capabilities>,original_state:Option<BatteryCareState>,target_enabled:Option<bool>,initial_snapshot:Option<Snapshot>,trial_apply:Option<ApplyReport>,target_snapshot:Option<Snapshot>,target_readback_confirmed:bool,restore_attempted:bool,restore_apply:Option<ApplyReport>,restored_snapshot:Option<Snapshot>,restore_readback_confirmed:bool,errors:Vec<(&'static str,DeviceError)>}
impl Report{pub fn success(&self)->bool{self.outcome==Outcome::ReadbacksConfirmed}fn new()->Self{Self{command:"--validate-battery-care-restore",outcome:Outcome::Rejected,message:String::new(),capabilities:None,original_state:None,target_enabled:None,initial_snapshot:None,trial_apply:None,target_snapshot:None,target_readback_confirmed:false,restore_attempted:false,restore_apply:None,restored_snapshot:None,restore_readback_confirmed:false,errors:vec![]}}fn finish(mut self,message:&str)->Self{self.message=message.into();self}}
trait BatteryDevice{fn capabilities(&mut self)->Result<Capabilities,DeviceError>;fn snapshot(&mut self)->Result<Snapshot,DeviceError>;fn toggle(&mut self)->Result<ApplyReport,DeviceError>;fn restore(&mut self)->Result<ApplyReport,DeviceError>;fn settle(&mut self);}
struct Native<'a>(&'a Device);impl BatteryDevice for Native<'_>{fn capabilities(&mut self)->Result<Capabilities,DeviceError>{self.0.capabilities()}fn snapshot(&mut self)->Result<Snapshot,DeviceError>{self.0.snapshot()}fn toggle(&mut self)->Result<ApplyReport,DeviceError>{self.0.begin_battery_care_validation()}fn restore(&mut self)->Result<ApplyReport,DeviceError>{self.0.restore_validation_battery_care()}fn settle(&mut self){std::thread::sleep(std::time::Duration::from_secs(2));}}
pub fn run(device:&Device)->Report{validate(&mut Native(device))}
fn accepted(report:&ApplyReport,target:bool)->bool{!matches!(report.status,ApplyStatus::Failed|ApplyStatus::Rejected)&&report.writes.len()==1&&battery_care_ack(&report.writes[0],target)==Some(true)}
fn validate(device:&mut impl BatteryDevice)->Report{
    let mut report=Report::new();let caps=match device.capabilities(){Ok(c)=>c,Err(e)=>{report.errors.push(("capabilities",e));return report.finish("Cannot verify target; no battery write attempted");}};
    let target=caps.matched_model&&acer_device::verified_fan_target(&caps.model,&caps.bios);report.capabilities=Some(caps);if !target{return report.finish("Requires PHN16-71/V1.18; no write attempted");}
    let before=match device.snapshot(){Ok(s)=>s,Err(e)=>{report.errors.push(("initial_read",e));return report.finish("Initial read failed; no write attempted");}};report.original_state=battery_validation_state(&before);report.initial_snapshot=Some(before);
    if report.original_state.is_none(){return report.finish("Requires supported/reliable health-mode bool and idle other battery functions; no calibration operation is allowed");}
    report.target_enabled=report.original_state.as_ref().map(|s|!s.enabled);
    let trial_ok=match device.toggle(){Ok(r)=>{if let Some(saved)=r.before.as_ref().and_then(battery_validation_state){report.target_enabled=Some(!saved.enabled);report.original_state=Some(saved);}let ok=accepted(&r,report.target_enabled.unwrap());report.trial_apply=Some(r);ok},Err(e)=>{report.errors.push(("health_mode_write",e));false}};
    if trial_ok{device.settle();match device.snapshot(){Ok(s)=>{report.target_readback_confirmed=battery_care_readback(&s,report.original_state.as_ref().unwrap(),report.target_enabled.unwrap());report.target_snapshot=Some(s);},Err(e)=>report.errors.push(("health_mode_read",e)),}}
    report.restore_attempted=true;let saved=report.original_state.as_ref().unwrap();
    let restore_ok=match device.restore(){Ok(r)=>{let ok=accepted(&r,saved.enabled);report.restore_apply=Some(r);ok},Err(e)=>{report.errors.push(("restore_write",e));false}};
    match device.snapshot(){Ok(s)=>{report.restore_readback_confirmed=restore_ok&&battery_care_readback(&s,saved,saved.enabled);report.restored_snapshot=Some(s);},Err(e)=>report.errors.push(("restored_read",e)),}
    report.outcome=if !report.restore_readback_confirmed{Outcome::RestoreUnconfirmed}else if trial_ok&&report.target_readback_confirmed&&report.errors.is_empty(){Outcome::ReadbacksConfirmed}else{Outcome::Failed};let message=if report.success(){"Health-mode bool inversion and original restore confirmed; other function states unchanged. Physical charge threshold was not measured."}else if report.restore_readback_confirmed{"Health-mode trial failed; original flag and other function states confirmed"}else{"Original health-mode restore remains unconfirmed; inspect saved bool and raw return/status arrays"};report.finish(message)
}
#[cfg(test)]mod tests{
    use super::*;use acer_protocol::{battery_care,encode,Command,ErrorKind,RawRead,RawValue};use std::collections::{BTreeMap,VecDeque};
    fn snapshot(enabled:bool)->Snapshot{let mut s:Snapshot=serde_json::from_str(include_str!("../../../crates/acer-protocol/tests/fixtures/phn16-71-elevated-read.json")).unwrap();let r=s.reads.iter_mut().find(|r|r.method=="GetBatteryHealthControlStatus").unwrap();if let Some(RawValue::Bytes(bytes))=r.output.get_mut("uFunctionStatus"){bytes[0]=u8::from(enabled);}s.battery_care=battery_care(r);s}
    fn applied(target:bool)->ApplyReport{let c=encode(&Command::SetBatteryCare{enabled:target}).unwrap().remove(0);ApplyReport{status:ApplyStatus::Unconfirmed,message:"fake".into(),before:Some(snapshot(false)),after:None,writes:vec![RawRead{class:c.class,method:c.method,input:c.input,output:BTreeMap::from([("uReturn".into(),RawValue::unsigned(0)),("uReservedOut".into(),RawValue::unsigned(0))]),error:None}]}}
    fn error()->DeviceError{DeviceError{kind:ErrorKind::Transport,message:"fake failure".into()}}
    struct Fake{reads:VecDeque<Result<Snapshot,DeviceError>>,trial:Option<Result<ApplyReport,DeviceError>>,restore:Option<Result<ApplyReport,DeviceError>>,calls:Vec<&'static str>}
    impl Fake{fn new()->Self{Self{reads:[Ok(snapshot(false)),Ok(snapshot(true)),Ok(snapshot(false))].into(),trial:Some(Ok(applied(true))),restore:Some(Ok(applied(false))),calls:vec![]}}}
    impl BatteryDevice for Fake{fn capabilities(&mut self)->Result<Capabilities,DeviceError>{Ok(Capabilities{model:"PHN16-71".into(),bios:"V1.18".into(),matched_model:true,items:vec![]})}fn snapshot(&mut self)->Result<Snapshot,DeviceError>{self.calls.push("read");self.reads.pop_front().unwrap()}fn toggle(&mut self)->Result<ApplyReport,DeviceError>{self.calls.push("toggle");self.trial.take().unwrap()}fn restore(&mut self)->Result<ApplyReport,DeviceError>{self.calls.push("restore");self.restore.take().unwrap()}fn settle(&mut self){self.calls.push("settle");}}
    #[test]fn inversion_and_original_restore_are_confirmed(){let mut f=Fake::new();assert!(validate(&mut f).success());assert_eq!(f.calls,["read","toggle","settle","read","restore","read"]);}
    #[test]fn originally_enabled_is_disabled_then_restored_enabled(){let mut f=Fake::new();f.reads=[Ok(snapshot(true)),Ok(snapshot(false)),Ok(snapshot(true))].into();let mut trial=applied(false);trial.before=Some(snapshot(true));f.trial=Some(Ok(trial));f.restore=Some(Ok(applied(true)));let r=validate(&mut f);assert!(r.success());assert_eq!(r.target_enabled,Some(false));assert!(r.original_state.unwrap().enabled);}
    #[test]fn calibration_or_unknown_health_bool_refuses(){for calibration in [false,true]{let mut f=Fake::new();let s=f.reads[0].as_mut().unwrap();if calibration{let r=s.reads.iter_mut().find(|r|r.method=="GetBatteryHealthControlStatus").unwrap();if let Some(RawValue::Bytes(bytes))=r.output.get_mut("uFunctionStatus"){bytes[1]=1;}}else{s.battery_care=None;}let r=validate(&mut f);assert_eq!(r.outcome,Outcome::Rejected);assert_eq!(f.calls,["read"]);}}
    #[test]fn trial_write_error_still_restores(){let mut f=Fake::new();f.trial=Some(Err(error()));f.reads.remove(1);let r=validate(&mut f);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_attempted&&r.restore_readback_confirmed);}
    #[test]fn trial_read_error_still_restores(){let mut f=Fake::new();f.reads[1]=Err(error());let r=validate(&mut f);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_readback_confirmed);}
    #[test]fn restore_error_is_explicit(){let mut f=Fake::new();f.restore=Some(Err(error()));let r=validate(&mut f);assert_eq!(r.outcome,Outcome::RestoreUnconfirmed);assert!(r.restore_attempted);}
}
